import{_ as r,C as o,o as i,c as n,j as t,a as s,E as l,a6 as c}from"./chunks/framework.CCKCzdWs.js";const b=JSON.parse('{"title":"Command line","description":"The piwi command the Playwright reporter package installs, by the moment you reach for it: set up, gate CI, pick the tests, chase a flake, write a test.","frontmatter":{"title":"Command line","description":"The piwi command the Playwright reporter package installs, by the moment you reach for it: set up, gate CI, pick the tests, chase a flake, write a test.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/command-line.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/command-line.html"}],["meta",{"property":"og:title","content":"Command line | Piwi for Playwright"}],["meta",{"property":"og:description","content":"The piwi command the Playwright reporter package installs, by the moment you reach for it: set up, gate CI, pick the tests, chase a flake, write a test."}]]},"headers":[],"relativePath":"features/command-line.md","filePath":"features/command-line.md","lastUpdated":1794864492000}'),h={name:"features/command-line.md"};function d(m,e,f,p,g,u){const a=o("Needs");return i(),n("div",null,[e[0]||(e[0]=t("h1",{id:"command-line",tabindex:"-1"},[s("Command line "),t("a",{class:"header-anchor",href:"#command-line","aria-label":'Permalink to "Command line"'},"​")],-1)),l(a,{reporter:""}),e[1]||(e[1]=c('<p>The <code>@piwitests/reporter</code> package installs a command, <code>piwi</code>, for what happens around a test run. Run it through the package name, <code>npx @piwitests/reporter &lt;command&gt;</code>, or as <code>npx piwi &lt;command&gt;</code> once the reporter is a dependency of the project. This page says which command serves which moment; every flag, and how a command finds the dashboard and its API key, is on the <a href="/reference/cli.html">Piwi CLI reference</a>.</p><h2 id="setting-up" tabindex="-1">Setting up <a class="header-anchor" href="#setting-up" aria-label="Permalink to &quot;Setting up&quot;">​</a></h2><ul><li><strong><a href="/reference/cli.html#init"><code>init</code></a></strong> wires a Playwright project up to a dashboard: the reporter, the <a href="/guide/capture-fixtures.html">capture fixtures</a>, a <code>.env</code> and the <a href="./agent-skills.html">agent skills</a>.</li><li><strong><a href="/reference/cli.html#skills"><code>skills</code></a></strong> installs or updates the agent skills in a project <code>init</code> did not set up.</li><li><strong><a href="/reference/cli.html#mcp"><code>mcp</code></a></strong> serves the runs of this machine&#39;s editors and desktop app to a coding agent (<a href="./agent-run-control.html">Run control for agents</a>).</li></ul><h2 id="in-ci" tabindex="-1">In CI <a class="header-anchor" href="#in-ci" aria-label="Permalink to &quot;In CI&quot;">​</a></h2><ul><li><strong><a href="/reference/cli.html#gate"><code>gate</code></a></strong> fails a job on the dashboard&#39;s analysis of the run: the <a href="./merge-gate.html">CI merge gate</a>.</li><li><strong><a href="/reference/cli.html#rerun"><code>rerun</code></a></strong> runs the tests a <a href="./ci-rerun.html">re-run in CI</a> asked for, in a GitLab, Bitbucket or Jenkins job.</li><li><strong><a href="/reference/cli.html#report"><code>report</code></a></strong> prints a <a href="./quality-reports.html">quality report</a>, for a scheduler to post.</li><li><strong><a href="/reference/cli.html#coverage"><code>coverage</code></a></strong> uploads another tool&#39;s coverage of a commit, for <a href="./combined-coverage.html">combined coverage</a>.</li></ul><h2 id="choosing-the-tests" tabindex="-1">Choosing the tests <a class="header-anchor" href="#choosing-the-tests" aria-label="Permalink to &quot;Choosing the tests&quot;">​</a></h2><ul><li><strong><a href="/reference/cli.html#select-run"><code>select</code> and <code>run</code></a></strong> resolve a saved <a href="./test-selection.html">test selection</a>, or the tests a diff reaches (<a href="./change-impact.html">Impact from a diff</a>), and print or run them.</li><li><strong><a href="/reference/cli.html#plan"><code>plan</code></a></strong> plans a run that reuses the passes whose code has not changed (<a href="./reuse-forecast.html">Reuse forecast</a>), an experimental capability.</li><li><strong><a href="/reference/cli.html#probe"><code>probe</code></a></strong> runs the dashboard&#39;s <a href="./probes.html">probe plan</a>.</li></ul><h2 id="chasing-a-flaky-test" tabindex="-1">Chasing a flaky test <a class="header-anchor" href="#chasing-a-flaky-test" aria-label="Permalink to &quot;Chasing a flaky test&quot;">​</a></h2><ul><li><strong><a href="/reference/cli.html#flake"><code>flake</code></a></strong> makes a flaky test fail on demand under its suspects&#39; conditions, then verifies the fix (<a href="./flake-lab.html">Flake Lab</a>).</li></ul><h2 id="writing-and-fixing-a-test" tabindex="-1">Writing and fixing a test <a class="header-anchor" href="#writing-and-fixing-a-test" aria-label="Permalink to &quot;Writing and fixing a test&quot;">​</a></h2><ul><li><strong><a href="/reference/cli.html#codegen"><code>codegen</code></a></strong> turns a Piwi Picker recording into a spec (<a href="./record-actions.html">Record actions</a>).</li><li><strong><a href="/reference/cli.html#bug"><code>bug</code></a></strong> writes a <a href="./bug-reports.html">bug report</a>&#39;s failing test into the project and runs it.</li><li><strong><a href="/reference/cli.html#preflight"><code>preflight</code></a></strong> lists the test locators your change breaks, and fixes them (<a href="./preflight.html">Locator preflight</a>).</li><li><strong><a href="/reference/cli.html#ai"><code>ai</code></a></strong> manages the committed artifacts of <a href="./ai-steps.html">AI steps</a>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/reference/cli.html">Piwi CLI</a>: every command and flag</li><li><a href="./write-run-fix.html">Write, run and fix a test</a>: the loop the editor, Piwi Picker and the desktop app share</li><li><a href="/guide/reporter.html">Reporter</a>: the package the command ships in</li></ul>',13))])}const w=r(h,[["render",d]]);export{b as __pageData,w as default};
